parameters.jsCode:
const src = $json;

let raw = src.output ?? src.response ?? src.result ?? src.text ?? src;
if (typeof raw === 'string') {
  try { raw = JSON.parse(raw); } catch {}
}
if (raw && typeof raw === 'object' && raw.output) raw = raw.output;

const plan = Array.isArray(raw?.sequential_plan) ? raw.sequential_plan : [];
const predicted = plan
  .map((s) => (typeof s?.agent_name === 'string' ? s.agent_name.trim() : ''))
  .filter(Boolean);

const expected = Array.isArray(src.expected_agent_sequence) ? src.expected_agent_sequence : [];
const expectedCount = Number(src.expected_agents_count ?? expected.length);

return {
  json: {
    ...src,
    predicted_agent_sequence: predicted,
    predicted_agents_count: predicted.length,
    count_match: predicted.length === expectedCount,
    sequence_match: JSON.stringify(predicted) === JSON.stringify(expected),
    raw_planner_output: raw
  }
};

const rows = $input.all().map((i) => i.json);
const total = rows.length;

const passedCount = rows.filter((r) => r.count_match).length;
const passedSeq = rows.filter((r) => r.sequence_match).length;

const failed = rows
  .filter((r) => !r.sequence_match || !r.count_match)
  .map((r) => ({
    id: r.id,
    request: r.request,
    expected_agent_sequence: r.expected_agent_sequence,
    expected_agents_count: r.expected_agents_count,
    predicted_agent_sequence: r.predicted_agent_sequence,
    predicted_agents_count: r.predicted_agents_count,
    count_match: r.count_match,
    sequence_match: r.sequence_match
  }));

return [{
  json: {
    total,
    exact_sequence_accuracy: total ? passedSeq / total : 0,
    count_accuracy: total ? passedCount / total : 0,
    passed_sequence: passedSeq,
    passed_count: passedCount,
    failed_cases: failed,
    results: rows
  }
}];

const payload = $json;
const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const fileName = `planner_eval_${stamp}.json`;
const content = JSON.stringify(payload, null, 2);

return [{
  json: payload,
  binary: {
    data: {
      data: Buffer.from(content, 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName
    }
  }
}];
